<?php defined('BASEPATH') or exit('No direct script access allowed');$discussionHidden=function(string $action)use($esc,$company_contracts_csrf,$contract,$discussion){echo '<input type="hidden" name="action" value="'.$esc($action).'"><input type="hidden" name="company_contracts_csrf" value="'.$esc($company_contracts_csrf).'"><input type="hidden" name="contract_id" value="'.(int)$contract['id'].'"><input type="hidden" name="revision" value="'.(int)$discussion['revision'].'"><input type="hidden" name="request_key" value="'.bin2hex(random_bytes(32)).'">';}; ?>
<section id="contract-discussion" class="company-settings-card"><h3>Conversa sobre o contrato</h3><p>Comentários não alteram texto, snapshot, numeração ou estado do contrato e não representam assinatura ou aceite jurídico. Mensagens da equipe são internas até publicação individual. Comentários do contato são destinados à equipe e aos contatos autorizados deste cadastro, no contrato publicado.</p>
<?php foreach($discussion['items'] as $comment){ ?><article><p style="white-space:pre-wrap"><?= $esc($comment['body']); ?></p><small><?= $esc(($comment['author_type']==='contact'?'Contato: ':'Funcionário: ').$comment['author_name']); ?> · <?= $esc($comment['created_at']); ?> · <?= (int)$comment['visible']===1?'Publicado para contatos autorizados':'Interno'; ?></small><?php if($can_edit){ ?><?= form_open($url());$discussionHidden('discussion_visibility'); ?><input type="hidden" name="comment_id" value="<?= (int)$comment['id']; ?>"><label><input type="checkbox" name="visible" value="1" <?= (int)$comment['visible']===1?'checked':''; ?>> Publicar este comentário para contatos autorizados</label><button type="submit">Salvar publicação do comentário</button><?= form_close(); ?><?php } ?></article><?php } ?>
<?php if($can_edit){ ?><?= form_open($url(),['id'=>'contract-discussion-add']);$discussionHidden('discussion_add'); ?><label for="contract-discussion-body">Novo comentário interno</label><textarea id="contract-discussion-body" name="discussion_body" maxlength="8000" rows="6" required></textarea><button type="submit">Registrar comentário interno</button><?= form_close(); ?><?php } ?></section>
